mode <- commandArgs(TRUE)[1]
source("pre.R")
if (mode == "attached") suppressPackageStartupMessages(library(bit64)) else if (mode == "loaded") invisible(loadNamespace("bit64"))
x <- int64(c(a=-1, b=5, c=NA))
show("as_integer64 names", names(as_integer64(x))); show("as_integer64 u64 names", names(as_integer64(setNames(uint64(1:2), c("p","q")))))
show("as_integer64(u64 big)", as_integer64(uint64("9223372036854775808"))); show("as_integer64(i128)", as_integer64(int128(c("-9223372036854775808","-9223372036854775807","9223372036854775807","9223372036854775808"))))
show("as_integer64(dec)", tryCatch(as_integer64(decimal128(c("1.50","2.00"),10,2)), error=function(e) conditionMessage(e)))
show("as_integer64(1L)", as_integer64(1L)); show("as_integer64('5')", as_integer64("5")); show("as_integer64(1.5)", tryCatch(as_integer64(1.5), error=function(e) conditionMessage(e))); show("as_integer64(2^53)", as_integer64(2^53)); show("as_integer64(NULL)", tryCatch(as_integer64(NULL), error=function(e) conditionMessage(e)))
show("int64(as_integer64) identical", identical(int64(as_integer64(x)), x))
show("zu_vapply convert", zu_vapply(1:2, function(i) uint64(5), int64(0))); show("zu_vapply lossy", zu_vapply(1:2, function(i) int64(-1), uint64(0))); show("zu_vapply dbl", zu_vapply(1:2, function(i) 2.5, int64(0))); show("zu_vapply int", zu_vapply(1:2, function(i) i, int128(0))); show("zu_vapply wrong len", tryCatch(zu_vapply(1:2, function(i) int64(1:2), int64(0)), error=function(e) conditionMessage(e)))
show("zu_vapply k=0", zu_vapply(1:2, function(i) int64(), int64())); show("zu_vapply chr", zu_vapply(1:2, function(i) "7", int64(0))); show("zu_vapply dec", zu_vapply(1:2, function(i) decimal128("1.239", 10, 3), decimal128("0", 10, 2)))
show("zu_vapply names k2", names(zu_vapply(c(a=1,b=2), function(i) int64(c(x=1,y=2)), int64(1:2))))
show("zu_ifelse mixed", zu_ifelse(c(TRUE,FALSE), int64(-1), uint64("18446744073709551614"))); show("zu_ifelse incompatible", tryCatch(zu_ifelse(TRUE, int64(1), uint128(1)), error=function(e) class(e)[1]))
show("zu_ifelse dbl 2.5", tryCatch(zu_ifelse(c(TRUE,FALSE), int64(1), 2.5), error=function(e) class(e)[1])); show("zu_ifelse yes longer", zu_ifelse(TRUE, int64(1:3), int64(9))); show("zu_ifelse chr test", tryCatch(zu_ifelse(c("TRUE","x"), int64(1), int64(2)), error=function(e) class(e)[1]))
show("zu_ifelse int test", zu_ifelse(c(0L, 2L, NA), int64(1), int64(2))); show("zu_ifelse both base", tryCatch(zu_ifelse(TRUE, 1L, 2L), error=function(e) class(e)[1])); show("zu_ifelse dec", zu_ifelse(c(TRUE,FALSE,NA), decimal128("1.5",10,1), int64(2)))
show("zu_ifelse dec type", vctrs::vec_ptype_full(zu_ifelse(c(TRUE,FALSE,NA), decimal128("1.5",10,1), int64(2)))); show("c dec type", vctrs::vec_ptype_full(c(decimal128("1.5",10,1), int64(2))))
show("zu_ifelse dec no rows", zu_ifelse(c(FALSE,FALSE), decimal128(c("1.5","2.5"),10,1), 7L)); show("zu_ifelse dec recycle no", zu_ifelse(c(FALSE,TRUE,FALSE), decimal128("1.5",10,1), decimal128(c("1.25","2.25","3.25"),10,2)))
show("zu_ifelse matrix test", zu_ifelse(matrix(c(TRUE,FALSE,TRUE,FALSE),2), int64(1), int64(2)))
show("seq(int64(10), int64(1))", tryCatch(seq(int64(10), int64(1)), error=function(e) conditionMessage(e))); show("seq(int64(1), int64(10), length.out=10)", tryCatch(seq(int64(1), int64(10), length.out=10), error=function(e) conditionMessage(e)))
show("seq(int64(5))", tryCatch(seq(int64(5)), error=function(e) conditionMessage(e))); show("seq along.with", seq(int64(3), along.with=1:4)); show("seq(int64(1), 2^40, by=2^39)", seq(int64(1), 2^40, by=2^39)); show("seq len 0", tryCatch(seq(int64(1), length.out=0), error=function(e) conditionMessage(e)))
show("seq by neg", seq(int64(3), int64(1), by=-1L)); show("seq(1L, int64(3))", seq(1L, int64(3))); show("seq u64 down", seq(uint64(3), uint64(0), by=-1L)); show("rev(seq)", rev(seq(int64(1), int64(3))))
show("cut(x, 2)", tryCatch(cut(int64(1:4), 2), error=function(e) conditionMessage(e)))
show("%*%", tryCatch(int64(1:2) %*% int64(1:2), error=function(e) conditionMessage(e))); show("%*% u64", tryCatch(uint64(1:2) %*% uint64(1:2), error=function(e) conditionMessage(e))); show("crossprod", tryCatch(crossprod(int128(1:2)), error=function(e) conditionMessage(e)))
show("as.matrix", tryCatch(as.matrix(int64(1:2)), error=function(e) conditionMessage(e))); show("dim<-", tryCatch({y <- int64(1:4); dim(y) <- c(2,2); y}, error=function(e) conditionMessage(e))); show("matrix()", matrix(int64(1:2))); show("t()", t(int64(1:2))); show("outer", tryCatch(outer(int64(1:2), int64(1:2)), error=function(e) conditionMessage(e))); show("diag", tryCatch(diag(int64(1:2)), error=function(e) conditionMessage(e)))
